-- Weekly Arena 2026-W47: generated by scripts/weekly-arena.ts. Safe to rerun (skips if the title already exists).
insert into public.arenas(title, description, starts_at, ends_at, duration_minutes, status, questions)
select 'Weekly Arena 2026-W47', 'Fresh weekly set of 10 numeric questions across Algebra, Geometry, Combinatorics and Number Theory. Each question allows three submissions. New questions every week, none repeated from earlier arenas.', '2026-11-16T00:00:00.000Z', '2026-11-23T00:00:00.000Z', 60, 'published', $WK4c4aa44c375a$[{"id":"wk-2026-w47-01-3777","title":"The Isosceles Trapezoid","topic":"Geometry","level":"Foundation","question":"An isosceles trapezoid has parallel sides of lengths $25$ and $11$ and each non-parallel side has length $25$. Find its area.","type":"text","correctAnswer":"432","hint":"Drop perpendiculars from the shorter base; each cuts off a right triangle with base $7$ and hypotenuse $25$.","solution":"The height is $\\sqrt{25^2-7^2}=24$, so the area is $\\tfrac12(25+11)(24)=432$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w47-02-a253","title":"Tangent and Secant","topic":"Geometry","level":"Intermediate","question":"From an external point $P$, a tangent $PT$ of length $7$ and a secant meeting the circle at $A$ and $B$ are drawn, with $PA < PB$ and $PA=1$. Find $PA + PB + PT$.","type":"text","correctAnswer":"57","hint":"Apply the power of a point: $PT^2=PA\\cdot PB$.","solution":"$PB=7^2/1=49$, so the sum is $1+49+7=57$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":3,"points":53,"difficulty":-0.28},{"id":"wk-2026-w47-03-0875","title":"A Blocked Lattice Path","topic":"Combinatorics","level":"Intermediate","question":"A path from $(0,0)$ to $(6,7)$ moves only one unit right or one unit up at each step. How many such paths avoid the point $(3,3)$?","type":"text","correctAnswer":"1016","hint":"Subtract the paths that pass through the forbidden point from the total.","solution":"$\\binom{13}{6}-\\binom{6}{3}\\binom{7}{3}=1016$.","answerMode":"numeric-grid","answerDigits":4,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w47-04-22ae","title":"Coprime Count","topic":"Number Theory","level":"Intermediate","question":"How many integers $n$ with $1\\le n\\le 627$ are relatively prime to $154$?","type":"text","correctAnswer":"244","hint":"Remove multiples of 2, 7, 11 using inclusion-exclusion.","solution":"Inclusion-exclusion over the primes 2, 7, 11 leaves $244$ integers.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w47-05-2022","title":"Reciprocal Powers","topic":"Algebra","level":"Intermediate","question":"A positive real number $x$ satisfies $x + \\dfrac{1}{x} = 6$. Find $x^{5} + \\dfrac{1}{x^{5}}$.","type":"text","correctAnswer":"6726","hint":"Set $T_m=x^m+x^{-m}$; then $T_m=6T_{m-1}-T_{m-2}$.","solution":"With $T_0=2$, $T_1=6$ the recurrence gives $T_{5}=6726$.","answerMode":"numeric-grid","answerDigits":4,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w47-06-21da","title":"Three Remainders","topic":"Number Theory","level":"Intermediate","question":"Find the smallest positive integer $n$ such that $n\\equiv 3 \\pmod{5}$, $n\\equiv 2 \\pmod{7}$, $n\\equiv 1 \\pmod{9}$.","type":"text","correctAnswer":"163","hint":"The moduli are pairwise coprime, so the Chinese Remainder Theorem gives a unique residue class.","solution":"Combining the congruences gives the residue class of $163$ modulo $315$, and $163$ is its smallest positive member.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w47-07-f03a","title":"Multiples of Two Numbers","topic":"Algebra","level":"Intermediate","question":"Find the sum of all positive integers not exceeding $202$ that are divisible by $4$ or by $9$ (or both).","type":"text","correctAnswer":"6837","hint":"Add the sum of multiples of each number, then subtract the multiples of their product that were counted twice.","solution":"Inclusion-exclusion over multiples of $4$, $9$ and $36$ gives $6837$.","answerMode":"numeric-grid","answerDigits":4,"maxAttempts":3,"estimatedSteps":4,"abstraction":2,"points":54,"difficulty":-0.24},{"id":"wk-2026-w47-08-a564","title":"Powers of the Roots","topic":"Algebra","level":"Advanced","question":"Let $r$ and $s$ be the roots of $t^2 - 3t + 2 = 0$. Find the remainder when $r^{8} + s^{8}$ is divided by $1000$.","type":"text","correctAnswer":"257","hint":"Let $S_k=r^k+s^k$. Then $S_k=3S_{k-1}-2S_{k-2}$, with $S_0=2$, $S_1=3$.","solution":"Using $S_k=3S_{k-1}-2S_{k-2}$ from $S_0=2$, $S_1=3$ gives $S_{8}=257$, whose remainder modulo $1000$ is $257$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w47-09-25f4","title":"Rearranging a Word","topic":"Combinatorics","level":"Advanced","question":"In how many distinct ways can the letters of $\\text{RRRPEMM}$ be rearranged so that no two identical letters are adjacent?","type":"text","correctAnswer":"96","hint":"Count all arrangements, then use inclusion-exclusion by gluing identical letters together.","solution":"Inclusion-exclusion (confirmed by exhaustive enumeration) gives $96$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":5,"abstraction":4,"points":73,"difficulty":0.52},{"id":"wk-2026-w47-10-7476","title":"Lattice Points Inside","topic":"Geometry","level":"Advanced","question":"A triangle has vertices $(0,0)$, $(7,10)$ and $(12,13)$ in the coordinate plane. How many points with integer coordinates lie strictly inside the triangle?","type":"text","correctAnswer":"14","hint":"Use Pick's theorem: $A=I+B/2-1$, with $B$ counted by gcds along each side.","solution":"Twice the area is $29$ and the boundary has $B=3$ lattice points, so $I=(29-3+2)/2=14$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0}]$WK4c4aa44c375a$::jsonb
